css:
.formula{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:stretch;gap:.5rem;margin-top:1.75rem}
.formula .op{align-self:center;font-family:"Bricolage Grotesque",sans-serif;font-size:2rem;font-weight:700;color:var(--muted)}
.term{font:inherit;text-align:left;border:2px solid var(--line);border-radius:16px;background:var(--card);color:var(--ink);padding:.75rem .9rem;cursor:pointer}
.term b{display:block;font-family:"Bricolage Grotesque",sans-serif;font-size:clamp(1.05rem,3.4vw,1.4rem);font-weight:700}
.term span{display:block;font-size:.95rem;color:var(--muted)}
.term[data-m="biotop"][aria-pressed="true"]{background:var(--cat1-bg);border-color:var(--cat1)}
.term[data-m="bioz"][aria-pressed="true"]{background:var(--cat2-bg);border-color:var(--cat2)}
.term[data-m="oeko"][aria-pressed="true"]{background:var(--accent-bg);border-color:var(--accent)}
@media (max-width:560px){.formula{grid-template-columns:1fr}.formula .op{text-align:center;font-size:1.5rem;line-height:1}}

.stage{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:.75rem;margin-top:1rem;overflow:hidden}
.scene{border-radius:14px;overflow:hidden}
#env{transition:filter .4s,opacity .4s}
.biotic,.lab-a,.lab-b,.links{transition:opacity .4s}
.m-biotop .biotic{opacity:.08}
.m-biotop .lab-b,.m-biotop .links{opacity:0}
.m-bioz #env{filter:grayscale(1);opacity:.45}
.m-bioz .lab-a,.m-bioz .links{opacity:0}
.m-oeko .lab-a,.m-oeko .lab-b{opacity:.0}
.m-oeko .links{opacity:1}
.m-biotop .links,.m-bioz .links{pointer-events:none}
.chip-a rect{fill:var(--cat1-bg);stroke:var(--cat1)}
.chip-a text{fill:var(--cat1)}
.chip-b rect{fill:var(--cat2-bg);stroke:var(--cat2)}
.chip-b text{fill:var(--cat2)}
.chip-e rect{fill:var(--accent-bg);stroke:var(--accent)}
.chip-e text{fill:var(--accent)}
.chip text{font-family:"Atkinson Hyperlegible",sans-serif;font-size:14px;font-weight:700}
.linkline{stroke:var(--accent);stroke-width:2;fill:none;stroke-dasharray:6 5}
@media (prefers-reduced-motion: no-preference){.m-oeko .linkline{animation:flow 1.4s linear infinite}}
@keyframes flow{to{stroke-dashoffset:-22}}
#explain{margin:1rem .5rem .25rem;font-size:1.05rem}
#explain strong{font-family:"Bricolage Grotesque",sans-serif}

script:
(function(){
const $=id=>document.getElementById(id), NS='http://www.w3.org/2000/svg';
function chip(parent,cls,x,y,txt){
  const g=document.createElementNS(NS,'g');g.setAttribute('class','chip '+cls);
  const w=txt.length*8.2+18;
  const r=document.createElementNS(NS,'rect');r.setAttribute('x',x);r.setAttribute('y',y);r.setAttribute('width',w);r.setAttribute('height',26);r.setAttribute('rx',13);r.setAttribute('stroke-width',1.2);
  const t=document.createElementNS(NS,'text');t.setAttribute('x',x+w/2);t.setAttribute('y',y+18);t.setAttribute('text-anchor','middle');t.textContent=txt;
  g.append(r,t);parent.append(g);
}
[[520,92,'Licht'],[160,190,'Wasser'],[485,176,'Temperatur'],[468,220,'Sauerstoff'],[190,352,'Schlamm und Boden'],[400,360,'Steine'],[560,120,'Luft']].forEach(a=>chip($('labA'),'chip-a',...a));
[[160,40,'Schilf'],[4,164,'Frosch'],[284,62,'Libelle'],[330,248,'Fisch'],[436,126,'Seerose'],[150,248,'Algen'],[372,300,'Schnecke']].forEach(a=>chip($('labB'),'chip-b',...a));
[[108,40,'frisst'],[468,262,'liefert O₂'],[500,106,'Licht für Pflanzen'],[244,292,'braucht O₂']].forEach(a=>chip($('labE'),'chip-e',...a));

const texts={
 biotop:'<strong>Biotop:</strong> Nur der Lebensraum, ohne Lebewesen. Licht, Wasser, Temperatur, Sauerstoff, Boden und Steine sind die unbelebten (abiotischen) Bedingungen.',
 bioz:'<strong>Biozönose:</strong> Alle Lebewesen, die im Weiher zusammenleben: Schilf, Seerose, Algen, Frosch, Fisch, Libelle, Schnecke und viele winzige Bakterien.',
 oeko:'<strong>Ökosystem:</strong> Lebensraum und Lebewesen zusammen. Die gestrichelten Pfeile zeigen, wie alles zusammenhängt: Wer frisst wen, wer braucht was, wer liefert was.'
};
function setMode(m){
  const sc=$('scene');sc.className='scene m-'+m;
  document.querySelectorAll('.term').forEach(b=>b.setAttribute('aria-pressed',b.dataset.m===m?'true':'false'));
  $('explain').innerHTML=texts[m];
}
document.querySelectorAll('.term').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.m)));
setMode('oeko');
})();
